                    StoryParagraph("Then he spoke in a voice full of bitter pain.", "بعد با صدایی پر از درد تلخ صحبت کرد."),
                    StoryParagraph("'I am the brother of the king,' he said quietly.", "«من برادر پادشاه هستم،» آرام گفت."),
                    StoryParagraph("'We are twins. We were born on the same night.'", "«ما دوقلو هستیم. در همان شب به دنیا آمدیم.»"),
                    StoryParagraph("'But only one of us could wear the crown.'", "«اما فقط یکی از ما می‌توانست تاج بگذارد.»"),
                    StoryParagraph("'So they locked me away and erased my name.'", "«پس مرا زندانی کردند و نامم را پاک کردند.»"),
                    StoryParagraph("'I have been here for twenty-three years.'", "«بیست و سه سال اینجا بوده‌ام.»"),
                    StoryParagraph("D'Artagnan was stunned by this revelation.", "دارتانیان از این افشاگری شوکه شد."),
                    StoryParagraph("He could barely believe what he was hearing.", "به سختی می‌توانست باور کند چه می‌شنود."),
                    StoryParagraph("'But this is a terrible injustice,' he said.", "«اما این بی‌عدالتی وحشتناکی است،» گفت."),
                    StoryParagraph("'You have been imprisoned for no crime.'", "«بدون هیچ جنایتی زندانی شده‌ای.»"),
                    StoryParagraph("'Justice,' the prisoner said bitterly, 'is for the powerful.'", "«عدالت،» زندانی تلخ گفت، «برای قدرتمندان است.»"),
                    StoryParagraph("'The weak and the inconvenient are simply locked away.'", "«ضعیفان و نامطلوب‌ها به سادگی زندانی می‌شوند.»"),
                    StoryParagraph("D'Artagnan left the cell with a heavy heart.", "دارتانیان با قلبی سنگین سلول را ترک کرد."),
                    StoryParagraph("He told his three friends everything that night.", "آن شب همه چیز را به سه دوستش گفت."),
                    StoryParagraph("Athos listened in thoughtful silence.", "آتوس در سکوت متفکر گوش داد."),
                    StoryParagraph("Porthos was angry and ready to fight immediately.", "پورتوس عصبانی شد و آماده جنگیدن فوری بود."),
                    StoryParagraph("Aramis prayed quietly for the prisoner's soul.", "آرامیس آرام برای روح زندانی دعا کرد."),
                    StoryParagraph("'We must help him,' D'Artagnan said firmly.", "«باید کمکش کنیم،» دارتانیان محکم گفت."),
                    StoryParagraph("'We must free him and restore his rights.'", "«باید آزادش کنیم و حقوقش را بازگردانیم.»"),
                    StoryParagraph("Athos nodded slowly.", "آتوس آرام سر تکان داد."),
                    StoryParagraph("'It will be dangerous,' he warned. 'Perhaps fatal.'", "«خطرناک خواهد بود،» هشدار داد. «شاید کشنده.»"),
                    StoryParagraph("'The Cardinal will never allow it.'", "«کاردینال هرگز اجازه نمی‌دهد.»"),
                    StoryParagraph("'The king himself may order our deaths.'", "«خود پادشاه ممکن است دستور مرگمان را بدهد.»"),
                    StoryParagraph("'But it is the right thing to do.'", "«اما کار درست است.»"),
                    StoryParagraph("'And we swore an oath to defend the innocent.'", "«و قسم خوردیم از بی‌گناهان دفاع کنیم.»"),
                    StoryParagraph("D'Artagnan smiled at his friend.", "دارتانیان به دوستش لبخند زد."),
                    StoryParagraph("'Then we will do it,' he said quietly.", "«پس انجامش می‌دهیم،» آرام گفت."),
                    StoryParagraph("'All for one, and one for all.'", "«همه برای یکی، و یکی برای همه.»"),
                    StoryParagraph("They began to plan the most dangerous mission of their lives.", "آن‌ها شروع کردند به نقشه کشیدن خطرناک‌ترین مأموریت زندگی‌شان."),
                    StoryParagraph("A mission that would shake the very foundations of France.", "مأموریتی که پایه‌های خود فرانسه را تکان می‌داد.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Secret of the Twin", titlePersian = "راز سلطنتی",
                paragraphs = listOf(
