            StoryChapter(
                number = 4, title = "The Fight for the Throne", titlePersian = "خطر بزرگ",
                paragraphs = listOf(
                    StoryParagraph("The musketeers entered the palace through a servant's door.", "تفنگداران از در خدمتکاران وارد قصر شدند."),
                    StoryParagraph("They moved silently through the dark corridors behind the ballroom.", "آن‌ها بی‌صدا از راهروهای تاریک پشت سالن بالماسکه گذشتند."),
                    StoryParagraph("The king's private chambers were at the end of a long hallway.", "اتاق‌های خصوصی پادشاه در انتهای راهرویی طولانی بودند."),
                    StoryParagraph("Two guards stood outside the door.", "دو نگهبان بیرون در ایستاده بودند."),
                    StoryParagraph("Porthos and Aramis dealt with them quietly.", "پورتوس و آرامیس بی‌صدا از عهده‌شان برآمدند."),
                    StoryParagraph("The musketeers entered the king's bedroom and waited.", "تفنگداران وارد اتاق خواب پادشاه شدند و منتظر ماندند."),
                    StoryParagraph("At midnight, the king came in alone.", "در نیمه‌شب، پادشاه تنها وارد شد."),
                    StoryParagraph("He was tired and a little drunk from the wine.", "او خسته و کمی مست از شراب بود."),
                    StoryParagraph("He stopped short when he saw the four men in his room.", "وقتی چهار مرد را در اتاقش دید، ناگهان ایستاد."),
                    StoryParagraph("'What is the meaning of this?' he demanded angrily.", "«معنی این چیست؟» خشمگین خواستار شد."),
                    StoryParagraph("Then he saw the face of his twin brother.", "بعد صورت برادر دوقلویش را دید."),
                    StoryParagraph("He stepped back with a cry of shock and fear.", "او با فریاد شوک و ترس عقب رفت."),
                    StoryParagraph("'You!' he gasped. 'It cannot be you!'", "«تو!» نفس‌نفس زد. «نمی‌تواند تو باشی!»"),
                    StoryParagraph("'Yes, brother,' the prisoner said quietly.", "«بله، برادر،» زندانی آرام گفت."),
                    StoryParagraph("'It is me. The one you locked away twenty-three years ago.'", "«من هستم. همان که بیست و سه سال پیش زندانی کردی.»"),
                    StoryParagraph("'The one whose name was erased from history.'", "«همان که نامش از تاریخ پاک شد.»"),
                    StoryParagraph("'The one who wore an iron mask for no crime.'", "«همان که بدون جنایتی نقاب آهنین پوشید.»"),
                    StoryParagraph("The king was pale and shaking.", "پادشاه رنگ‌پریده و لرزان بود."),
                    StoryParagraph("'You do not understand,' he stammered. 'I had no choice!'", "«نمی‌فهمی،» لکنت کرد. «انتخابی نداشتم!»"),
                    StoryParagraph("'The council decided. The state required it.'", "«شورا تصمیم گرفت. دولت لازم داشت.»"),
                    StoryParagraph("'The state,' the prisoner repeated bitterly. 'Always the state.'", "«دولت،» زندانی تلخ تکرار کرد. «همیشه دولت.»"),
                    StoryParagraph("'But what about me? What about my life?'", "«اما من چه؟ زندگی من چه؟»"),
                    StoryParagraph("The king did not answer.", "پادشاه جواب نداد."),
                    StoryParagraph("He could not answer.", "نمی‌توانست جواب دهد."),
                    StoryParagraph("D'Artagnan stepped forward and spoke firmly.", "دارتانیان جلو آمد و محکم صحبت کرد."),
                    StoryParagraph("'Your Majesty, you must abdicate the throne.'", "«اعلیحضرت، باید از تخت کناره‌گیری کنید.»"),
                    StoryParagraph("'Your brother will rule in your place.'", "«برادرتان به جای شما حکومت می‌کند.»"),
                    StoryParagraph("The king stared at him with fury and disbelief.", "پادشاه با غضب و ناباوری نگاهش کرد."),
                    StoryParagraph("'You are traitors!' he shouted. 'You will all hang for this!'", "«شما خائن هستید!» فریاد زد. «همه‌تان برای این دار زده می‌شوید!»"),
                    StoryParagraph("'We are not traitors,' D'Artagnan said calmly.", "«ما خائن نیستیم،» دارتانیان آرام گفت."),
                    StoryParagraph("'We are servants of justice. True justice, not royal convenience.'", "«ما خدمتکاران عدالت هستیم. عدالت واقعی، نه راحتی سلطنتی.»"),
                    StoryParagraph("The king tried to escape but Porthos blocked the door.", "پادشاه تلاش کرد فرار کند اما پورتوس در را بست."),
                    StoryParagraph("'Give me your royal robes,' D'Artagnan ordered.", "«لباس سلطنتی‌تان را بدهید،» دارتانیان دستور داد."),
                    StoryParagraph("The king refused at first, but had no choice.", "پادشاه اول امتناع کرد، اما انتخابی نداشت."),
                    StoryParagraph("The musketeers dressed the twin brother in the royal clothes.", "تفنگداران برادر دوقلو را در لباس‌های سلطنتی پوشاندند."),
                    StoryParagraph("They put the king in a common soldier's uniform.", "آن‌ها پادشاه را در یونیفرم سرباز معمولی پوشاندند."),
                    StoryParagraph("Then they led the real king out the back of the palace.", "بعد پادشاه واقعی را از پشت قصر بیرون بردند."),
                    StoryParagraph("They took him to the Bastille and locked him in the iron mask.", "آن‌ها او را به باستیل بردند و در نقاب آهنین زندانی کردند."),
